"""PiLENS: full MoViNet-A1 run in ONE Kaggle cell (feature extraction + binary MIL + crime type + ONNX export + paper_pack).
How to run:
  1. Open the MoViNet-A0 Kaggle notebook and "Copy & Edit" it (dataset, GPU and Internet settings stay the same).
     Check settings: Accelerator = GPU T4 (or P100), Internet = ON.
  2. Delete all old cells, add one code cell and paste this whole file.
  3. "Save Version" -> "Save & Run All (Commit)". Kaggle runs it by itself (about 1.5 to 2.5 hours).
  4. When done, download from the notebook Output, "download" folder:
       paper_pack.zip             (results)
       export_movinet_a1_v2.zip   (for the Pi)
It embeds the tested scripts (m_step1..4 + step8) with VARIANT = "A1". Protocol, split and seeds are the same as A0.
"""
import os, sys, zlib, base64, hashlib, subprocess, time, glob

SCRIPTS = [
    ("m_step1_extract_movinet.py", "", "9a207aa804de"),
    ("m_step2_binary_mil.py", "", "6cb9b12ea5a4"),
    ("m_step3_14class.py", "", "792242184599"),
    ("m_step4_export_onnx.py", "", "1dcb4a760100"),
    ("step8_save_results.py", "", "f50750e63c5f"),
]

print("SCRIPT VERSION: a1_kaggle_all v1.0 (2026-10-11) | MODE: FULL | VARIANT: A1 (MoViNet-A1, 172 px, 13 frames)")
W = "/kaggle/working"; SRC = os.path.join(W, "pilens_a1_src"); os.makedirs(SRC, exist_ok=True)
for name, blob, sha in SCRIPTS:
    s = zlib.decompress(base64.b64decode(blob)).decode()
    assert hashlib.sha256(s.encode()).hexdigest()[:12] == sha, "file kharab ho gayi: " + name
    if name.startswith("m_"):
        assert 'VARIANT = "A1"' in s
    open(os.path.join(SRC, name), "w").write(s)
print("scripts ready:", ", ".join(n for n, _, _ in SCRIPTS))

T0 = time.time()
for name, _, _ in SCRIPTS:
    print("\n" + "=" * 70 + f"\n>>> {name}   (shuru: {(time.time() - T0) / 60:.0f} min par)\n" + "=" * 70, flush=True)
    p = subprocess.Popen([sys.executable, "-u", os.path.join(SRC, name)], cwd=W, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    for line in p.stdout:
        print(line, end="", flush=True)
    if p.wait() != 0:
        raise SystemExit(f"\nROKO: {name} fail hua (exit {p.returncode}). Upar wala error copy karke chat mein bhejo.")

TAG = "movinet_a1_v2"
checks = [
    ("features (32x2048 per video)", len(glob.glob(f"{W}/feats_{TAG}/*.npy")) >= 1900),
    ("binary eval_pack.npz", os.path.exists(f"{W}/binary_out_{TAG}/eval_pack.npz")),
    ("classes cls14_pack.npz", os.path.exists(f"{W}/cls14_out_{TAG}/cls14_pack.npz")),
    ("ONNX export heads_meta.json", os.path.exists(f"{W}/export_{TAG}/heads_meta.json")),
    ("download/paper_pack.zip", os.path.exists(f"{W}/download/paper_pack.zip")),
    ("download/export_movinet_a1_v2.zip", os.path.exists(f"{W}/download/export_movinet_a1_v2.zip")),
]
print("\n" + "=" * 70 + f"\nA1 RUN SUMMARY (kul {(time.time() - T0) / 60:.0f} min)")
for k, ok in checks:
    print(("  OK    " if ok else "  MISSING ") + k)
print("A1 RUN COMPLETE: paper_pack.zip chat mein bhejo, export_movinet_a1_v2.zip Pi par." if all(ok for _, ok in checks) else "KUCH MISSING HAI: ye summary chat mein bhejo.")
print("END OF REPORT")
